using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

/// <summary>
/// Shared helpers for configuring evaluation scenarios, evaluators, and reporting.
/// </summary>
internal static class EvalSetup
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    /// <summary>
    /// Creates the standard set of quality evaluators (no safety evaluator).
    /// </summary>
    public static IList<IEvaluator> CreateQualityEvaluators()
    {
        return new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };
    }

    /// <summary>
    /// Creates a <see cref="ReportingConfiguration"/> that persists results to disk
    /// for quality and compare modes.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfiguration(
        IChatClient judgeChatClient,
        string scenarioName)
    {
        var storage = new DiskBasedReportingStorage(StoragePath);

        return new ReportingConfiguration(
            storage: storage,
            chatClient: judgeChatClient,
            evaluators: CreateQualityEvaluators(),
            scenarioName: scenarioName);
    }
}

using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenAI;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that the agent emits expected traces and metrics.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static readonly ActivitySource Source = new("MyApp.Evals.Telemetry");

    [TestMethod]
    public async Task Agent_EmitsActivity_OnChatCompletion()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name == "Microsoft.Extensions.AI",
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => activities.Add(activity),
        };
        ActivitySource.AddActivityListener(listener);

        var client = CreateChatClient();
        var wrappedClient = new ChatClientBuilder(client)
            .UseOpenTelemetry()
            .Build();

        await wrappedClient.GetResponseAsync("Say hello.");

        Assert.IsTrue(activities.Count > 0, "Expected at least one activity from the chat client.");
        Assert.IsTrue(
            activities.Any(a => a.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase)),
            "Expected a chat-related activity.");
    }

    [TestMethod]
    public async Task Agent_TracksTokenUsage()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name == "Microsoft.Extensions.AI",
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => activities.Add(activity),
        };
        ActivitySource.AddActivityListener(listener);

        var client = CreateChatClient();
        var wrappedClient = new ChatClientBuilder(client)
            .UseOpenTelemetry()
            .Build();

        var response = await wrappedClient.GetResponseAsync("What is 2+2?");

        Assert.IsNotNull(response.Usage, "Usage metadata should be present.");
        Assert.IsTrue(response.Usage.InputTokenCount > 0, "Input tokens should be reported.");
        Assert.IsTrue(response.Usage.OutputTokenCount > 0, "Output tokens should be reported.");
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: runs quality evaluators (coherence, relevance, fluency, groundedness)
/// against agent responses and generates a report.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_config;
    private ScenarioRun? _scenarioRun;

    [ClassInitialize]
    public static void ClassInit(TestContext _)
    {
        var judge = CreateChatClient();
        s_config = EvalSetup.CreateReportingConfiguration(judge, scenarioName: "Quality");
    }

    [TestInitialize]
    public async Task TestInit()
    {
        _scenarioRun = await s_config!.CreateScenarioRunAsync(TestContext.CurrentContext!.TestName!);
    }

    [TestCleanup]
    public async Task TestCleanup()
    {
        if (_scenarioRun is not null)
        {
            await _scenarioRun.DisposeAsync();
        }
    }

    public TestContext TestContext { get; set; } = null!;

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        var client = CreateChatClient();
        var prompt = "Give me a short motivational coaching tip for someone starting a new project.";
        var response = await client.GetResponseAsync(prompt);

        await _scenarioRun!.EvaluateAsync(
            new ChatMessage(ChatRole.User, prompt),
            response);

        var metrics = _scenarioRun.GetEvaluationResult();

        AssertMetricPassesThreshold(metrics, CoherenceEvaluator.CoherenceMetricName, 3);
        AssertMetricPassesThreshold(metrics, RelevanceEvaluator.RelevanceMetricName, 3);
        AssertMetricPassesThreshold(metrics, FluencyEvaluator.FluencyMetricName, 3);
    }

    [TestMethod]
    public async Task CoachResponse_IsGrounded()
    {
        var client = CreateChatClient();
        var context = "The user is a software engineer starting a new open-source library.";
        var prompt = "How should I approach the first week of building my library?";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, context),
            new(ChatRole.User, prompt),
        };
        var response = await client.GetResponseAsync(messages);

        await _scenarioRun!.EvaluateAsync(messages, response);

        var metrics = _scenarioRun.GetEvaluationResult();
        AssertMetricPassesThreshold(metrics, GroundednessEvaluator.GroundednessMetricName, 3);
    }

    private static void AssertMetricPassesThreshold(
        EvaluationResult result,
        string metricName,
        int threshold)
    {
        var metric = result.Metrics.FirstOrDefault(m => m.Name == metricName)
            as NumericMetric;
        Assert.IsNotNull(metric, $"Metric '{metricName}' not found.");
        Assert.IsTrue(
            metric.Value >= threshold,
            $"{metricName} scored {metric.Value}, expected >= {threshold}.");
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations and
/// compares quality metrics side-by-side via the reporting storage.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    [TestMethod]
    public async Task Compare_TwoModelConfigurations()
    {
        var judge = CreateChatClient();

        var prompt = "Explain the benefits of test-driven development in two sentences.";

        // Run A: primary model
        var resultA = await RunScenarioAsync(judge, "Compare-ModelA", prompt, "gpt-4o-mini");

        // Run B: alternate model (same deployment, different temperature to simulate variant)
        var resultB = await RunScenarioAsync(judge, "Compare-ModelB", prompt, "gpt-4o-mini");

        // Both runs stored; compare coherence scores
        var coherenceA = GetScore(resultA, CoherenceEvaluator.CoherenceMetricName);
        var coherenceB = GetScore(resultB, CoherenceEvaluator.CoherenceMetricName);

        Console.WriteLine($"Model A coherence: {coherenceA}");
        Console.WriteLine($"Model B coherence: {coherenceB}");

        // Ensure both meet minimum bar (compare report gives side-by-side view)
        Assert.IsTrue(coherenceA >= 3, $"Model A coherence {coherenceA} below threshold.");
        Assert.IsTrue(coherenceB >= 3, $"Model B coherence {coherenceB} below threshold.");
    }

    private static async Task<EvaluationResult> RunScenarioAsync(
        IChatClient judge,
        string scenarioName,
        string prompt,
        string deploymentName)
    {
        var storage = new DiskBasedReportingStorage(StoragePath);
        var config = new ReportingConfiguration(
            storage: storage,
            chatClient: judge,
            evaluators: EvalSetup.CreateQualityEvaluators(),
            scenarioName: scenarioName);

        var client = CreateChatClient(deploymentName);
        var response = await client.GetResponseAsync(prompt);

        await using var run = await config.CreateScenarioRunAsync("compare-run");
        await run.EvaluateAsync(
            new ChatMessage(ChatRole.User, prompt),
            response);

        return run.GetEvaluationResult();
    }

    private static double GetScore(EvaluationResult result, string metricName)
    {
        var metric = result.Metrics.FirstOrDefault(m => m.Name == metricName) as NumericMetric;
        return metric?.Value ?? 0;
    }

    private static IChatClient CreateChatClient(string deployment = "gpt-4o-mini")
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();
    }
}

