using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenAI;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that the agent emits expected traces and metrics.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static readonly ActivitySource Source = new("MyApp.Evals.Telemetry");

    [TestMethod]
    public async Task Agent_EmitsActivity_OnChatCompletion()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name == "Microsoft.Extensions.AI",
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => activities.Add(activity),
        };
        ActivitySource.AddActivityListener(listener);

        var client = CreateChatClient();
        var wrappedClient = new ChatClientBuilder(client)
            .UseOpenTelemetry()
            .Build();

        await wrappedClient.GetResponseAsync("Say hello.");

        Assert.IsTrue(activities.Count > 0, "Expected at least one activity from the chat client.");
        Assert.IsTrue(
            activities.Any(a => a.DisplayName.Contains("chat", StringComparison.OrdinalIgnoreCase)),
            "Expected a chat-related activity.");
    }

    [TestMethod]
    public async Task Agent_TracksTokenUsage()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name == "Microsoft.Extensions.AI",
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => activities.Add(activity),
        };
        ActivitySource.AddActivityListener(listener);

        var client = CreateChatClient();
        var wrappedClient = new ChatClientBuilder(client)
            .UseOpenTelemetry()
            .Build();

        var response = await wrappedClient.GetResponseAsync("What is 2+2?");

        Assert.IsNotNull(response.Usage, "Usage metadata should be present.");
        Assert.IsTrue(response.Usage.InputTokenCount > 0, "Input tokens should be reported.");
        Assert.IsTrue(response.Usage.OutputTokenCount > 0, "Output tokens should be reported.");
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

